import { useEffect, useState } from 'react';
import { api } from '../../api/api';
import PageHeader from '../../components/PageHeader';

export default function AdminResults() {
  const [results, setResults] = useState([]);
  useEffect(() => { api('/admin/results').then(setResults); }, []);

  return (
    <div>
      <PageHeader title="Results" subtitle="All recorded subject results" />
      <div className="card">
        <table className="table table--striped">
          <thead>
            <tr><th>Student</th><th>Class</th><th>Subject</th><th>Term</th><th>Total</th><th>Grade</th><th>Remark</th></tr>
          </thead>
          <tbody>
            {results.map((r) => (
              <tr key={r.id}>
                <td>{r.studentName}</td><td>{r.className}</td><td>{r.subject}</td>
                <td>{r.term}</td><td><strong>{r.total}</strong></td>
                <td><span className={`grade grade--${r.grade}`}>{r.grade}</span></td>
                <td>{r.remark}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
